'use client'

import { useEffect, useState } from 'react'
import { Button } from '@/components/ui/button'

import MenuDropdown from '@/components/supernova/hero-section-41/blocks/menu-dropdown'
import MenuNavigation from '@/components/supernova/hero-section-41/blocks/menu-navigation'
import type { NavigationSection } from '@/components/supernova/hero-section-41/blocks/menu-navigation'

import { cn } from '@/lib/utils'

import BistroLogo from '@/components/supernova/hero-section-41/assets/svg/bistro-logo'
import { MenuIcon } from 'lucide-react'

type HeaderProps = {
  navigationData: NavigationSection[]
  className?: string
}

const Header = ({ navigationData, className }: HeaderProps) => {
  const [isScrolled, setIsScrolled] = useState(false)

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 0)
    }

    window.addEventListener('scroll', handleScroll)
    handleScroll()

    return () => {
      window.removeEventListener('scroll', handleScroll)
    }
  }, [])

  return (
    <header
      className={cn(
        'fixed top-0 z-50 h-17.5 w-full border-b transition-all duration-300',
        {
          'bg-background shadow-md': isScrolled
        },
        className
      )}
    >
      <div className='mx-auto flex h-full max-w-7xl items-center justify-between gap-6 px-4 sm:px-6 lg:px-8'>
        {/* Logo */}
        <a href='#' className='flex items-center gap-3'>
          <BistroLogo />
          <span className='text-primary text-[20px] font-semibold'>Bistro</span>
        </a>

        {/* Navigation */}
        <MenuNavigation
          navigationData={navigationData}
          className='max-lg:hidden [&_[data-slot=navigation-menu-list]]:gap-1'
        />

        {/* Actions */}
        {/* Navigation for small screens */}
        <div className='flex gap-3'>
          <Button size='lg' className='rounded-full' render={<a href='#' />} nativeButton={false}>
            Book table
          </Button>

          <MenuDropdown
            align='end'
            navigationData={navigationData}
            trigger={
              <Button variant='outline' size='icon-lg' className='rounded-full lg:hidden'>
                <MenuIcon />
                <span className='sr-only'>Menu</span>
              </Button>
            }
          />
        </div>
      </div>
    </header>
  )
}

export default Header

'use client'

import { useEffect, useState, useCallback, useSyncExternalStore } from 'react'
import { useReducedMotion } from 'motion/react'

import Autoplay from 'embla-carousel-autoplay'
import { Separator } from '@/components/ui/separator'

import { Button } from '@/components/ui/button'
import { type CarouselApi, Carousel, CarouselContent, CarouselItem } from '@/components/ui/carousel'
import { cn } from '@/lib/utils'
import { ArrowRightIcon } from 'lucide-react'

export type MenuData = {
  id: number
  img: string
  imgAlt: string
  userAvatar: string
  userComment: string
}

const HeroSection = ({ menudata }: { menudata: MenuData[] }) => {
  const [mainApi, setMainApi] = useState<CarouselApi>()
  const [thumbApi, setThumbApi] = useState<CarouselApi>()
  const [commentsApi, setCommentsApi] = useState<CarouselApi>()
  const reduceMotion = useReducedMotion()
  const subscribe = useCallback((onChange: () => void) => {
    mainApi?.on('select', onChange)
    return () => { mainApi?.off('select', onChange) }
  }, [mainApi])
  const current = useSyncExternalStore(subscribe, () => mainApi?.selectedScrollSnap() ?? 0, () => 0)

  useEffect(() => {
    if (!mainApi) {
      return
    }

    const sync = () => {
      const selectedIndex = mainApi.selectedScrollSnap()

      // Sync all carousels with main carousel
      thumbApi?.scrollTo(selectedIndex)
      commentsApi?.scrollTo(selectedIndex)
    }
    mainApi.on('select', sync)
    return () => { mainApi.off('select', sync) }
  }, [mainApi, thumbApi, commentsApi])

  useEffect(() => {
    if (!thumbApi) {
      return
    }

    const sync = () => {
      const selectedIndex = thumbApi.selectedScrollSnap()

      // Sync main and comments carousel with thumbnail carousel
      mainApi?.scrollTo(selectedIndex)
      commentsApi?.scrollTo(selectedIndex)
    }
    thumbApi.on('select', sync)
    return () => { thumbApi.off('select', sync) }
  }, [thumbApi, mainApi, commentsApi])

  useEffect(() => {
    if (!commentsApi) {
      return
    }

    const sync = () => {
      const selectedIndex = commentsApi.selectedScrollSnap()

      // Sync main and thumbnail carousel with comments carousel
      mainApi?.scrollTo(selectedIndex)
      thumbApi?.scrollTo(selectedIndex)
    }
    commentsApi.on('select', sync)
    return () => { commentsApi.off('select', sync) }
  }, [commentsApi, mainApi, thumbApi])

  const handleThumbClick = useCallback(
    (index: number) => {
      mainApi?.scrollTo(index)
    },
    [mainApi]
  )

  const [plugin] = useState(() => Autoplay({ delay: 3000, stopOnInteraction: true }))

  return (
    <section className='flex-1 py-12 sm:py-16 lg:py-24'>
      <div className='mx-auto flex h-full max-w-7xl flex-col gap-16 px-4 sm:px-6 lg:px-8'>
        {/* Hero Header */}
        <div className='grid grid-cols-1 gap-6 gap-y-12 md:gap-y-16 lg:grid-cols-5'>
          <div className='flex w-full flex-col justify-center gap-5 max-lg:items-center lg:col-span-3 lg:h-95.5'>
            <h1 className='text-3xl leading-[1.29167] font-semibold text-balance max-lg:text-center sm:text-4xl lg:text-5xl'>
              Savor the taste of perfection
            </h1>

            <p className='text-muted-foreground max-w-xl text-xl max-lg:text-center'>
              Welcome to Restaurant where passion meets the plate.From sizzling appetisers to signature desserts, every
              dish is crafted to delight your senses.
            </p>

            <div className='flex items-center gap-4'>
              <Button
                size='lg'
                className='group relative w-fit overflow-hidden rounded-full text-base before:absolute before:inset-0 before:rounded-[inherit] before:bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.5)_50%,transparent_75%,transparent_100%)] before:bg-size-[250%_250%,100%_100%] before:bg-position-[200%_0,0_0] before:bg-no-repeat before:transition-[background-position_0s_ease] before:duration-1000 hover:before:bg-position-[-100%_0,0_0] dark:before:bg-[linear-gradient(45deg,transparent_25%,rgba(0,0,0,0.2)_50%,transparent_75%,transparent_100%)]'
                render={<a href='#' />}
                nativeButton={false}
              >
                Order now
                <ArrowRightIcon className='transition-transform duration-200 group-hover:translate-x-0.5' />
              </Button>
              <Button
                size='lg'
                className='bg-primary/10 hover:bg-primary/20 [a]:hover:bg-primary/20 text-primary rounded-full text-base'
                render={<a href='#' />}
                nativeButton={false}
              >
                Book table
              </Button>
            </div>
          </div>

          <Carousel
            className='w-full lg:col-span-2'
            setApi={setMainApi}
            plugins={reduceMotion ? [] : [plugin]}
            opts={{
              loop: true
            }}
          >
            <CarouselContent>
              {menudata.map(item => (
                <CarouselItem key={item.id} className='flex w-full items-center justify-center'>
                  <img src={item.img} alt={item.imgAlt} className='size-95 object-contain' />
                </CarouselItem>
              ))}
            </CarouselContent>
          </Carousel>
        </div>

        <div className='grid grid-cols-1 gap-24 gap-y-12 md:gap-y-16 lg:grid-cols-5'>
          <Carousel
            className='relative w-full max-lg:order-2 lg:col-span-3'
            setApi={setThumbApi}
            opts={{
              loop: true
            }}
          >
            <div className='from-background pointer-events-none absolute inset-y-0 left-0 z-1 w-25 bg-linear-to-r via-85% to-transparent' />
            <div className='from-background pointer-events-none absolute inset-y-0 right-0 z-1 w-25 bg-linear-to-l via-85% to-transparent' />
            <CarouselContent className='my-1 flex'>
              {menudata.map((item, index) => (
                <CarouselItem
                  key={item.id}
                  className={cn(
                    'basis-1/2 cursor-pointer items-center sm:basis-1/3 md:basis-1/4 lg:basis-1/3 xl:basis-1/4'
                  )}
                  onClick={() => handleThumbClick(index)}
                >
                  <div className='relative flex h-33 items-center justify-center'>
                    <div className={cn('absolute bottom-0 -z-1', current === index ? 'text-primary' : 'text-border')}>
                      <svg xmlns='http://www.w3.org/2000/svg' width='161' height='92' viewBox='0 0 161 92' fill='none'>
                        <path
                          d='M0.682517 80.6118L0.501193 39.6946C0.480127 34.9409 3.80852 30.8294 8.46241 29.8603L148.426 0.713985C154.636 -0.579105 160.465 4.16121 160.465 10.504V80.7397C160.465 86.2674 155.98 90.7465 150.453 90.7397L10.6701 90.5674C5.16936 90.5607 0.706893 86.1125 0.682517 80.6118Z'
                          stroke='currentColor'
                        />
                      </svg>
                    </div>
                    <img src={item.img} alt={item.imgAlt} className='size-25' />
                  </div>
                </CarouselItem>
              ))}
            </CarouselContent>
          </Carousel>
          <Carousel
            className='flex w-full items-center justify-center lg:col-span-2'
            setApi={setCommentsApi}
            opts={{
              loop: true
            }}
          >
            <CarouselContent>
              {menudata.map(item => (
                <CarouselItem
                  key={item.id}
                  className='flex h-full min-h-14 w-full items-center justify-center gap-4 px-6'
                >
                  <img
                    src={item.userAvatar}
                    alt={item.imgAlt}
                    className='border-background size-10 rounded-full border-4 drop-shadow-lg'
                  />
                  <Separator
                    orientation='vertical'
                    className='bg-primary hidden h-6! w-0.5! rounded-full! data-vertical:self-center sm:block'
                  />
                  <p className='text-card-foreground'>{item.userComment}</p>
                </CarouselItem>
              ))}
            </CarouselContent>
          </Carousel>
        </div>
      </div>
    </section>
  )
}

export default HeroSection

'use client'

import type { ReactElement, ReactNode } from 'react'
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger
} from '@/components/ui/dropdown-menu'
import { ChevronRightIcon, CircleSmallIcon } from 'lucide-react'

export type NavigationItem = {
  title: string
  href: string
}

export type NavigationSection = {
  title: string
  icon?: ReactNode
} & (
  | {
      items: NavigationItem[]
      href?: never
    }
  | {
      items?: never
      href: string
    }
)

type Props = {
  trigger: ReactElement
  navigationData: NavigationSection[]
  align?: 'center' | 'end' | 'start'
}

const MenuDropdown = ({ trigger, navigationData, align = 'start' }: Props) => {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={trigger}></DropdownMenuTrigger>
      <DropdownMenuContent className='w-56' align={align}>
        {navigationData.map(navItem => {
          if (navItem.href) {
            return (
              <DropdownMenuItem key={navItem.title} render={<a href={navItem.href} />}>
                {navItem.icon}
                {navItem.title}
              </DropdownMenuItem>
            )
          }

          return (
            <Collapsible key={navItem.title} render={<DropdownMenuGroup />}>
              <CollapsibleTrigger
                nativeButton={false}
                render={<DropdownMenuItem closeOnClick={false} className='group justify-between' />}
              >
                {navItem.icon}
                <span className='flex-1'>{navItem.title}</span>
                <ChevronRightIcon className='shrink-0 transition-transform group-data-panel-open:rotate-90' />
              </CollapsibleTrigger>
              <CollapsibleContent className='pl-2'>
                {navItem.items?.map(item => (
                  <DropdownMenuItem key={item.title} render={<a href={item.href} />}>
                    <CircleSmallIcon />
                    <span>{item.title}</span>
                  </DropdownMenuItem>
                ))}
              </CollapsibleContent>
            </Collapsible>
          )
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

export default MenuDropdown

import type { ReactNode } from 'react'

import {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle
} from '@/components/ui/navigation-menu'

import { cn } from '@/lib/utils'

export type NavigationItem = {
  title: string
  href: string
}

export type NavigationSection = {
  title: string
  icon?: ReactNode
} & (
  | {
      items: NavigationItem[]
      href?: never
    }
  | {
      items?: never
      href: string
    }
)

type MenuNavigationProps = {
  navigationData: NavigationSection[]
  className?: string
  align?: 'start' | 'center' | 'end'
}

const MenuNavigation = ({ navigationData, className, align = 'start' }: MenuNavigationProps) => {
  return (
    <NavigationMenu className={className} align={align}>
      <NavigationMenuList className='flex-wrap justify-start gap-1.5'>
        {navigationData.map(navItem => {
          if (navItem.href) {
            // Root link item
            return (
              <NavigationMenuItem key={navItem.title}>
                <NavigationMenuLink
                  href={navItem.href}
                  className={cn(
                    navigationMenuTriggerStyle(),
                    'text-muted-foreground hover:text-primary focus:text-primary dark:hover:bg-accent/50 bg-transparent! px-3 py-1.5 text-base!'
                  )}
                >
                  {navItem.title}
                </NavigationMenuLink>
              </NavigationMenuItem>
            )
          }

          // Section with dropdown
          return (
            <NavigationMenuItem key={navItem.title}>
              <NavigationMenuTrigger className='dark:data-open:hover:bg-accent/50 text-muted-foreground hover:text-primary focus:text-primary dark:hover:bg-accent/50 bg-transparent px-3 py-1.5 text-base [&>svg]:size-4'>
                {navItem.title}
              </NavigationMenuTrigger>
              <NavigationMenuContent className='data-[motion=from-start]:slide-in-from-left-30! data-[motion=to-start]:slide-out-to-left-30! data-[motion=from-end]:slide-in-from-right-30! data-[motion=to-end]:slide-out-to-right-30! w-auto'>
                <ul className='grid w-38 gap-4'>
                  <li>
                    {navItem.items?.map(item => (
                      <NavigationMenuLink key={item.title} href={item.href}>
                        {item.title}
                      </NavigationMenuLink>
                    ))}
                  </li>
                </ul>
              </NavigationMenuContent>
            </NavigationMenuItem>
          )
        })}
      </NavigationMenuList>
    </NavigationMenu>
  )
}

export default MenuNavigation
